  -- PioBlk : ----------------------------------------------------------------
  -- This block handles wiring of the RegPort between the communication
  -- interface and all the RegPort requesters.
  ----------------------------------------------------------------------------
  PioBlk : block

    signal bRegPortOutFromVi : RegPortOut_t;
    signal bRegPortOutLoc : RegPortOut_t;

  begin

    -------------------------------------------
    -- Interface to the communication interface
    -------------------------------------------
    bRegPortInLoc <= BuildRegPortIn(bRegPortIn);
    bRegPortOut <= to_StdLogicVector(bRegPortOutLoc);

    -------------------------------------------
    -- Interface to the RegPort requesters
    -------------------------------------------
    BusClkMiteIoLikeToReshold <= bRegPortIn;

    bRegPortOutFromVi <= BuildRegPortOut(BusClkMiteIoLikeFromReshold);

    BuildRegPortOut: process(bRegPortOutIrqArray, bRegPortOutFromVi)
      variable RegPortOutTemp : RegPortOut_t;
    begin

      RegPortOutTemp := bRegPortOutFromVi;

      for i in kNumberOfIrqs-1 downto 0 loop
        RegPortOutTemp.Data := RegPortOutTemp.Data or bRegPortOutIrqArray(i).Data;
        RegPortOutTemp.DataValid := RegPortOutTemp.DataValid or bRegPortOutIrqArray(i).DataValid;
        RegPortOutTemp.Ready := RegPortOutTemp.Ready and bRegPortOutIrqArray(i).Ready;
      end loop;

      bRegPortOutLoc <= RegPortOutTemp;

    end process BuildRegPortOut;

  end block PioBlk;

