  -- IrqBlk : ----------------------------------------------------------------
  -- This block instantiates IRQ logic and hooks up the IRQ requesters and
  -- the communication interface to the IRQ logic.
  ----------------------------------------------------------------------------
  IrqBlk : block

    signal IrqClkArray          : IrqClkArray_t;
    signal iIrqInArray          : IrqInArray_t;
    signal iIrqOutArray         : IrqOutArray_t;
    signal iIrqStatusInArray    : IrqStatusInArray_t;
    signal iIrqStatusOutArray   : IrqStatusOutArray_t;
    signal bIpIrq               : std_logic;

  begin

    GenerateIrqComponent : for i in 0 to kNumberOfIrqs-1 generate

      -- Tie the IP IRQ to the status line.  We are not currently supporting clear
      -- functionality.
      
      -- When Clear functionality will be implemented, must be checked if it's
      -- safe to pass this vector to a double sync (CAR #434493)
      
      bIpIrqToInterface(i).Status <= bIpIrq;
      bIpIrqToInterface(i).Clear <= '0';

      ----------------------------------------------
      -- Dynamically generated connections
      -- between IRQ requesters and the IRQ module.
      -- BEGIN
      ----------------------------------------------
        -- Wiring the Irq ports
  -- FPGA VI Interrupt Ports
  IrqClkArray(0) <= BusClk;
  iIrqOutArray(0).EnableClear <= '0';
  iIrqOutArray(0).EnableIn <= '0';
  iIrqStatusOutArray(0).EnableClear <= '0';
  iIrqStatusOutArray(0).EnableIn <= '0';
  -- IP Interrupt Port
  bIpIrq <= '0';


      ----------------------------------------------
      -- Dynamically generated connections
      -- between IRQ requesters and the IRQ module.
      -- END
      ----------------------------------------------

      DmaPortCommIfcLvFpgaIrqx: entity work.DmaPortCommIfcLvFpgaIrq (rtl)
        port map (
          aDiagramReset     => to_Boolean(reset),
          aBusReset         => to_Boolean(aBusReset),
          BusClk            => BusClk,
          bReset            => false,
          IrqClk            => IrqClkArray(i),
          iIrqEnableIn      => iIrqOutArray(i).EnableIn,
          iIrqEnableOut     => iIrqInArray(i).EnableOut,
          iIrqEnableClear   => iIrqOutArray(i).EnableClear,
          iIrqNum           => iIrqOutArray(i).IrqNum,
          iIrqAckStatus           => iIrqStatusInArray(i).Status,
          iIrqAckStatusEnableIn   => iIrqStatusOutArray(i).EnableIn,
          iIrqAckStatusEnableOut  => iIrqStatusInArray(i).EnableOut,
          iIrqAckStatusEnableClear => iIrqStatusOutArray(i).EnableClear,
          bIpIrqToInterface   => bIpIrqToInterface(i),
          bRegPortIn        => bRegPortInLoc,
          bRegPortOut       => bRegPortOutIrqArray(i),
          bIrqToInterface   => bIrqToInterfaceArray(i));

    end generate GenerateIrqComponent;

    bIrqToInterface <= to_StdLogicVector(bIrqToInterfaceArray);

  end block IrqBlk;

end architecture rtl;
